import java.io.BufferedReader
import java.io.InputStreamReader

fun isLeap(year: Int): Int {
    return if (year % 4 == 0 && year % 100 != 0 || year % 400 == 0) 29 else 28
}

fun daysInMonth(mon: Int, year: Int): Int = when (mon) {
    1 -> 31
    2 -> isLeap(year)
    3 -> 31
    4 -> 30
    5 -> 31
    6 -> 30
    7 -> 31
    8 -> 31
    9 -> 30
    10 -> 31
    11 -> 30
    12 -> 31
    else -> 0
}

fun noOfDaysRemaining(mon: Int, year: Int): Int {
    var days = 0
    if (mon < 1 || mon > 12) return 0
    for (m in mon..12) days += daysInMonth(m, year)
    return days
}

fun noOfDaysPassed(mon: Int, year: Int): Int {
    var days = 0
    if (mon < 1 || mon > 12) return 0
    for (m in 1..mon) days += daysInMonth(m, year)
    return days
}

fun noOfDays(year: Int): Int {
    val k = 31 * 7 + 30 * 4 + isLeap(year)
    return k
}

