        d2 = dd2
    } else {
        m1 = mm2
        y1 = yy2
        d1 = dd2
        m2 = mm1
        y2 = yy1
        d2 = dd1
    }
    val nodA = noOfDaysRemaining(m1, y1)
    val nodC = noOfDaysPassed(m2 - 1, y2)
    val start: Int
    val end: Int
    if (yy2 > yy1) {
        start = yy1
        end = yy2
    } else {
        start = yy2
        end = yy1
    }
    var nodB = 0
    for (i in (y1 + 1)..(y2 - 1)) {
